{
  "code": "export default async function ({ page }) {
  const EMAIL = 'jessicamendesbarbosa5@gmail.com';
  const SENHA = 'amovoced28';
  const w = (ms) => new Promise(r => setTimeout(r, ms));
  let d = [];

  try {
    await page.evaluateOnNewDocument(() => {
      Object.defineProperty(navigator, 'webdriver', { get: () => false });
      window.chrome = { runtime: {} };
    });
    await page.setUserAgent('Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36');
    await page.setViewport({ width: 1280, height: 800 });

    // LOGIN
    await page.goto('https://app.cotadorsimplificado.com.br/login', { waitUntil: 'domcontentloaded', timeout: 15000 });
    await w(500);
    const eInp = await page.$('#email_principal');
    if (eInp) { await eInp.type(EMAIL, { delay: 5 }); }
    await w(200);
    await page.evaluate(() => { const b = [...document.querySelectorAll('button')].find(x => x.textContent.includes('Continuar com Email')); if(b) b.click(); });
    await w(1500);
    const pwd = await page.$('#pwdInput');
    if (pwd) { await pwd.type(SENHA, { delay: 5 }); }
    await w(200);
    await page.evaluate(() => { const b = [...document.querySelectorAll('button')].find(x => x.textContent.trim() === 'Entrar'); if(b) b.click(); });
    await w(2000);
    d.push('L');

    // PRODUTO
    await page.goto('https://app.cotadorsimplificado.com.br/?produto=hap', { waitUntil: 'domcontentloaded', timeout: 15000 });
    await w(1500);
    d.push('P');

    // PME
    const pmeResult = await page.evaluate(() => { const p = [...document.querySelectorAll('.clickable-element')].find(e => e.textContent.includes('PME') && e.textContent.includes('29')); if(p) { p.click(); return 'clicked'; } return 'not found'; });
    await w(1000);
    d.push('M:' + pmeResult.substring(0,5));

    // NOME + AVANCAR 1
    const nInp = await page.$('#id-nomelead');
    if (nInp) { await nInp.type('teste', { delay: 5 }); d.push('N'); } else { d.push('N:no'); }
    await w(300);
    await page.evaluate(() => { const btns = document.querySelectorAll('button'); for(const b of btns) { const s = getComputedStyle(b); if(b.textContent.includes('Avan') && s.display !== 'none' && s.visibility !== 'hidden') { b.click(); break; } } });
    await w(1500);
    d.push('1');

    // CIDADE
    const cInp = await page.$('#cidade_nome');
    if (cInp) { await cInp.type('teresina', { delay: 30 }); d.push('C'); } else { d.push('C:no'); }
    await w(800);
    const tc = await page.evaluate(() => { for(const el of document.querySelectorAll('.clickable-element')) { if(el.textContent.trim() === 'Teresina - PI') { const r = el.getBoundingClientRect(); if(r.width > 0) return {x: r.x+r.width/2, y: r.y+r.height/2}; } } return null; });
    if (tc) { await page.mouse.click(tc.x, tc.y); d.push('T'); } else { d.push('T:no'); }
    await w(500);

    // MEI + AVANCAR 2
    try { await page.select('select.Dropdown', '"mei___empres_rio_individual"'); d.push('I'); } catch(e) { d.push('I:no'); }
    await w(300);
    await page.evaluate(() => { const btns = document.querySelectorAll('button'); for(const b of btns) { const s = getComputedStyle(b); if(b.textContent.includes('Avan') && s.display !== 'none' && s.visibility !== 'hidden') { b.click(); break; } } });
    await w(1500);
    d.push('2');

    // FAIXAS + AVANCAR 3
    const fxCount = await page.evaluate(() => { let c = 0; document.querySelectorAll('input').forEach(inp => { const r = inp.getBoundingClientRect(); const s = getComputedStyle(inp); if(r.width > 0 && s.display !== 'none' && !inp.id && inp.placeholder === '0' && inp.className.includes('cocys')) { inp.value = '1'; inp.dispatchEvent(new Event('input', {bubbles:true})); inp.dispatchEvent(new Event('change', {bubbles:true})); c++; } }); return c; });
    d.push('F:' + fxCount);
    await w(500);
    await page.evaluate(() => { const btns = document.querySelectorAll('button'); for(const b of btns) { const s = getComputedStyle(b); if(b.textContent.includes('Avan') && s.display !== 'none' && s.visibility !== 'hidden') { b.click(); break; } } });
    await w(2000);
    d.push('3');

    // ADD PRODUTOS
    const addResult = await page.evaluate(() => { const btns = document.querySelectorAll('button'); for(const b of btns) { const s = getComputedStyle(b); if(b.textContent.trim() === 'Add Produtos' && s.display !== 'none') { b.click(); return 'clicked'; } } return 'not found'; });
    d.push('A:' + addResult.substring(0,5));
    await w(1500);

    // HAPVIDA
    const hc = await page.evaluate(() => { for(const el of document.querySelectorAll('.clickable-element')) { if(el.textContent.trim() === 'Hapvida') { const r = el.getBoundingClientRect(); if(r.width > 0) return {x: r.x+r.width/2, y: r.y+r.height/2}; } } return null; });
    if (hc) { await page.mouse.click(hc.x, hc.y); d.push('H'); } else { d.push('H:no'); }
    await w(1500);

    // TABELA
    const tb = await page.evaluate(() => { for(const el of document.querySelectorAll('.clickable-element')) { const t = el.textContent.trim(); if(t.includes('Teresina') && t.includes('2') && t.includes('29')) { const r = el.getBoundingClientRect(); if(r.width > 0) return {x: r.x+r.width/2, y: r.y+r.height/2, text: t.substring(0,30)}; } } return null; });
    if (tb) { await page.mouse.click(tb.x, tb.y); d.push('TB'); } else { d.push('TB:no'); }
    await w(1000);

    // AMBULATORIAL
    const ab = await page.evaluate(() => { for(const el of document.querySelectorAll('.clickable-element')) { if(el.textContent.trim() === 'Ambulatorial') { const r = el.getBoundingClientRect(); if(r.width > 0) return {x: r.x+r.width/2, y: r.y+r.height/2}; } } return null; });
    if (ab) { await page.mouse.click(ab.x, ab.y); d.push('AM'); } else { d.push('AM:no'); }
    await w(800);

    // ACOMODACAO
    const ac = await page.evaluate(() => { for(const el of document.querySelectorAll('.clickable-element')) { const t = el.textContent.trim().toLowerCase(); if(t.includes('sem acomod') && t.includes('copartic')) { const r = el.getBoundingClientRect(); if(r.width > 0) return {x: r.x+r.width/2, y: r.y+r.height/2}; } } return null; });
    if (ac) { await page.mouse.click(ac.x, ac.y); d.push('AC'); } else { d.push('AC:no'); }
    await w(800);

    // FECHA MODAL
    await page.mouse.click(1200, 400);
    await w(1500);
    d.push('X');

    // DEBUG: Mostra conteudo da pagina
    const pageDebug = await page.evaluate(() => {
      const text = document.body.innerText.substring(0, 800);
      const hasValues = text.match(/\d{2,3}[,.]\d{2}/g) || [];
      const clickables = [...document.querySelectorAll('.clickable-element')].map(e => e.textContent.trim().substring(0,20)).slice(0,10);
      return { text: text.substring(0, 400), values: hasValues.slice(0,15), clickables };
    });

    return { success: true, debug: d.join('-'), pageDebug };
  } catch (error) {
    return { success: false, error: error.message, debug: d.join('-') };
  }
}"
}
